const $=id=>document.getElementById(id); let expedientes=load();let currentPre=null,currentInspection=null,currentMotor=null,currentClose=null,deferredPrompt=null,showLCFields=false;
function load(){try{let v=JSON.parse(localStorage.getItem(STORAGE)||'null');return Array.isArray(v)?v:structuredClone(SEED)}catch{return structuredClone(SEED)}}function persist(){localStorage.setItem(STORAGE,JSON.stringify(expedientes))}function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function foldName(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[._,;:/\\\-]+/g,' ').replace(/\s+/g,' ')}function titleName(v){return String(v??'').trim().toLowerCase().replace(/\b([a-záéíóúñ])/g,m=>m.toUpperCase())}function levenshtein(a,b){a=foldName(a);b=foldName(b);let p=Array.from({length:b.length+1},(_,i)=>i),c=[];for(let i=1;i<=a.length;i++){c=[i];for(let j=1;j<=b.length;j++)c[j]=Math.min(c[j-1]+1,p[j]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));p=c}return p[b.length]}function canonical(v,map){let f=foldName(v);if(map[f])return map[f];for(const [k,val] of Object.entries(map)){if(f.length>4&&levenshtein(f,k)<=1)return val}return titleName(v)}function normalizeCase(e){
e.distritoOriginal??=e.distrito||'';e.lugarOriginal??=e.lugar||'';e.distrito=canonical(e.distrito,DISTRICT_ALIASES);e.lugar=canonical(e.lugar,PLACE_ALIASES);
e.ingreso=e.ingreso||'Nuevo ingreso';e.modalidad=e.modalidad||'SIMPLE';
if(Array.isArray(e.pre)){if(!e.preLegacy)e.preLegacy=e.pre.slice();e.pre={}}else if(!e.pre||typeof e.pre!=='object')e.pre={};
e.cond=e.cond&&typeof e.cond==='object'?e.cond:{};e.inspection=e.inspection||{};
if(!Array.isArray(e.inspection.accesos)){let legacyHas=[e.inspection.anchoCallePlanoMadre,e.inspection.anchoCalleInspeccion,e.inspection.distanciaDesdeLC,e.inspection.distanciaDesdeLCInspeccion,e.inspection.acceso].some(v=>v!==undefined&&v!==null&&v!=='');e.inspection.accesos=[{tipo:e.inspection.acceso||'Calle pública',anchoPlano:e.inspection.anchoCallePlanoMadre??null,anchoInspeccion:e.inspection.anchoCalleInspeccion??null,referencia:e.inspection.referenciaMedicion||'ANCHO_TOTAL',desdeLC:e.inspection.distanciaDesdeLC??null,desdeLCInspeccion:e.inspection.distanciaDesdeLCInspeccion??null,observacion:''}];if(legacyHas)e.inspection.guardada=true}
if(!e.inspection.accesos.length)e.inspection.accesos=[emptyAccess()];e.inspection.accesos.forEach(a=>{a.desdeLCInspeccion??=null;if(a.tipo==='Acceso excepcional'||a.tipo==='Servidumbre')a.tipo='Servidumbre de paso (Acceso excepcional)'});e.defectIds=Array.isArray(e.defectIds)?e.defectIds:[];e.manualRejects=Array.isArray(e.manualRejects)?e.manualRejects:[];e.report=e.report||{};if(!e.finalizado)updateDecision(e);return e
}expedientes.forEach(normalizeCase);function go(page){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelectorAll('.nav [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('pageTitle').textContent={tramites:'Módulo de Trámites',pre:'Precalificación',inspection:'Inspección de Campo',calificacion:'Calificación',cierre:'Resoluciones e Informes'}[page]||'C-VISADOS';renderAll()}document.querySelectorAll('.nav [data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
$('fSearch').oninput=renderTable;$('fDistrict').onchange=renderTable;$('fPlace').oninput=renderTable;

function isoUTC(d){return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`}
function parseISODate(s){let m=String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return null;let d=new Date(Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3])));return Number.isNaN(d.getTime())?null:d}
function easterSunday(year){let a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=((h+l-7*m+114)%31)+1;return new Date(Date.UTC(year,month-1,day))}
function costaRicaHolidays(year){let fixed=[[1,1],[4,11],[5,1],[7,25],[8,2],[8,15],[8,31],[9,15],[12,1],[12,25]],set=new Set(fixed.map(([m,d])=>`${year}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`)),e=easterSunday(year);for(const delta of [-3,-2]){let x=new Date(e);x.setUTCDate(x.getUTCDate()+delta);set.add(isoUTC(x))}return set}
function isCRBusinessDay(d){let day=d.getUTCDay();if(day===0||day===6)return false;return !costaRicaHolidays(d.getUTCFullYear()).has(isoUTC(d))}
function businessDaysSince(start,endDate){let startD=parseISODate(start);if(!startD)return null;let end=endDate instanceof Date?new Date(Date.UTC(endDate.getFullYear(),endDate.getMonth(),endDate.getDate())):parseISODate(endDate);if(!end)end=new Date();if(end.getTime()<=startD.getTime())return 0;let n=0,d=new Date(startD);d.setUTCDate(d.getUTCDate()+1);while(d<=end){if(isCRBusinessDay(d))n++;d.setUTCDate(d.getUTCDate()+1)}return n}
function ageInfo(e,endDate){let days=businessDaysSince(e?.fecha,endDate);if(days===null)return {days:null,className:'',label:'Sin fecha'};if(days>=15)return {days,className:'red',rowClass:'aging-red',label:`${days} días hábiles`};if(days>10)return {days,className:'amber',rowClass:'aging-orange',label:`${days} días hábiles`};return {days,className:'blue',rowClass:'',label:`${days} días hábiles`}}
function statusPill(e){let c=e.finalizado?'green':e.estado?.includes('INSPE')?'amber':e.estado?.includes('MOTOR')?'blue':'amber';return `<span class="pill ${c}">${esc(e.estado||'REGISTRADO')}</span>`}function renderAll(){expedientes.forEach(e=>{normalizeCase(e);if(!e.finalizado)updateDecision(e)});renderKpis();renderDistrictFilter();renderTable();renderPreSelect();renderInspectionSelect();renderMotorSelect();renderCloseSelect();persist()}
function renderKpis(){let total=expedientes.length,final=expedientes.filter(x=>x.finalizado).length,rej=expedientes.filter(x=>x.dictamen==='RECHAZADO').length,apr=expedientes.filter(x=>x.dictamen==='APROBADO').length;$('kpis').innerHTML=[['Total',total],['Aprobados',apr],['Rechazados',rej],['Finalizados',final]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function renderDistrictFilter(){let v=$('fDistrict').value,ds=[...new Set(expedientes.map(x=>canonical(x.distrito,DISTRICT_ALIASES)).filter(Boolean))].sort();$('fDistrict').innerHTML='<option value="">Todos</option>'+ds.map(x=>`<option>${esc(x)}</option>`).join('');$('fDistrict').value=v}
function renderTable(){
 let sQ=foldName($('fSearch').value),d=$('fDistrict').value,pQ=foldName($('fPlace').value);
 let active=expedientes.filter(e=>!e.finalizado);
 let rows=active.filter(e=>(!sQ||foldName([e.tramite,e.solicitante,e.folio,e.plano].join(' ')).includes(sQ))&&(!d||e.distrito===d)&&(!pQ||foldName(e.lugar).includes(pQ)));
 if(!sQ&&!d&&!pQ){
   let groups=[...new Set(active.map(e=>e.distrito||'Sin distrito'))].sort((a,b)=>a.localeCompare(b,'es'));
   $('expBody').innerHTML=groups.length?groups.map(name=>{let items=active.filter(e=>(e.distrito||'Sin distrito')===name),places=[...new Set(items.map(e=>e.lugar).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),rej=items.filter(e=>e.dictamen==='RECHAZADO').length,red=items.filter(e=>ageInfo(e).days>=15).length,orange=items.filter(e=>{let a=ageInfo(e);return a.days>10&&a.days<15}).length;return `<tr class="click district-row" onclick="selectDistrictGroup('${String(name).replaceAll("'","\\'")}')"><td colspan="2"><b class="district-name">${esc(name)}</b><div class="district-summary"><span>${items.length} trámite(s)</span><span>${places.length} lugar(es)</span>${rej?`<span>${rej} con causal(es)</span>`:''}${orange?`<span class="age-summary amber">${orange} >10 días hábiles</span>`:''}${red?`<span class="age-summary red">${red} ≥15 días hábiles</span>`:''}</div></td><td colspan="5"><span class="small">${esc(places.slice(0,5).join(' · ')||'Sin lugar registrado')}${places.length>5?' · …':''}</span></td><td><span class="pill blue">Abrir distrito</span></td><td></td></tr>`}).join(''):'<tr><td colspan="9" class="empty">Sin expedientes en proceso</td></tr>';
   return;
 }
 $('expBody').innerHTML=rows.length?rows.map(e=>{let age=ageInfo(e);return `<tr class="click ${age.rowClass||''}" onclick="openCase(${e.id})"><td><b>${esc(e.tramite)}</b></td><td>${esc(e.fecha||'Sin fecha')}<div><span class="pill ${age.className||'blue'} age-pill" title="Días hábiles: lunes a viernes, excluyendo feriados oficiales de Costa Rica">${esc(age.label)}</span></div></td><td>${esc(e.folio||'')}<div class="small">${esc(e.plano||'')}</div></td><td>${esc(e.presentacion||e.asiento||'')}</td><td>${esc(e.solicitante||'')}</td><td>${esc(e.distrito||'')}<div class="small">${esc(e.lugar||'')}</div></td><td>${statusPill(e)}</td><td><span class="pill ${e.dictamen==='RECHAZADO'?'red':e.dictamen==='APROBADO'?'green':'amber'}">${e.dictamen}</span></td><td><button class="btn" onclick="event.stopPropagation();deleteCase(${e.id})">Eliminar</button></td></tr>`}).join(''):'<tr><td colspan="9" class="empty">Sin resultados</td></tr>'
}
function selectDistrictGroup(name){$('fDistrict').value=name==='Sin distrito'?'':name;renderTable()}
function clearFilters(){$('fSearch').value='';$('fDistrict').value='';$('fPlace').value='';renderTable()}function toggleNew(){$('newCard').style.display=$('newCard').style.display==='none'?'block':'none'}
function saveNew(){let tr=$('nTramite').value.trim();if(!tr){alert('Ingrese el número de trámite.');return}if(expedientes.some(x=>foldName(x.tramite)===foldName(tr))){alert('Ese trámite ya existe.');return}let id=Math.max(0,...expedientes.map(x=>Number(x.id)||0))+1;let e=normalizeCase({id,tramite:tr,fecha:$('nFecha').value,solicitante:$('nSolicitante').value,correo:$('nCorreo').value,folio:$('nFolio').value,plano:$('nPlano').value,presentacion:$('nPresent').value,tomo:$('nTomo').value,asiento:$('nAsiento').value,area:$('nArea').value,distrito:$('nDistrito').value,lugar:$('nLugar').value,ingreso:$('nIngreso').value,modalidad:$('nModalidad').value,responsable:$('nResponsable').value,estado:'EN PRECALIFICACIÓN',pre:{},cond:{},inspection:{accesos:[emptyAccess()]},defectIds:[],manualRejects:[],calificacionEncargado:'',dictamen:'PENDIENTE',finalizado:false,report:{}});expedientes.push(e);persist();toggleNew();document.querySelectorAll('#newCard input').forEach(x=>{if(x.id!=='nResponsable')x.value=''});renderAll()}
function deleteCase(id){if(!confirm('¿Eliminar este expediente local?'))return;expedientes=expedientes.filter(x=>x.id!==id);renderAll()}function openCase(id){currentPre=currentInspection=currentMotor=currentClose=id;go('pre')}
function options(rows,current){return rows.map(e=>`<option value="${e.id}" ${e.id===current?'selected':''}>${esc(e.tramite)} · ${esc(e.estado||'')}</option>`).join('')}

function modalityName(m){return {SIMPLE:'Fraccionamiento simple',URBANISTICO:'Fines urbanísticos',ACCESO_EXCEPCIONAL:'Acceso excepcional residencial',AGROPECUARIO:'Agrícola / pecuario / forestal / mixto'}[m]||m}
function activeRequirements(e){if(!e)return[];if(e.ingreso==='Reingreso')return REQUISITOS.REINGRESO;if(e.ingreso==='Resello')return REQUISITOS.RESELLO;return [...REQUISITOS.GENERAL_NUEVO,...(REQUISITOS[e.modalidad]||[])]}
