function renderQualificationSide(e){let state=updateDecision(e),inh=inheritedReasons(e),manual=e.manualRejects||[];$('decisionBox').className='statusbox '+(state.decision==='APROBADO'?'green':state.decision==='RECHAZADO'?'red':'amber');$('decisionBox').textContent=state.decision==='APROBADO'?'APROBADO · Sin motivos de rechazo':state.decision==='RECHAZADO'?`RECHAZADO · ${state.reasons.length} motivo(s)`:'PENDIENTE · Complete la inspección';$('flowSummary').innerHTML=[`<span class="flow-chip ${state.pre.complete?'green':'red'}">Precalificación ${state.pre.ok}/${state.pre.total}</span>`,`<span class="flow-chip ${state.inspection.complete?(state.inspection.match?'green':'red'):'amber'}">Inspección ${state.inspection.complete?(state.inspection.match?'conforme':'con diferencia'):'pendiente'}</span>`,`<span class="flow-chip ${e.defectIds.length?'red':'green'}">Calificación ${e.defectIds.length} causal(es)</span>`].join('');$('inheritedRejects').innerHTML=inh.length?inh.map(x=>`<div class="inherited-item"><span class="inherited-tag">${esc(x.source)}</span><b>${esc(x.label)}</b><div>${esc(x.motivation)}</div>${x.fund?`<div class="small">${esc(x.fund)}</div>`:''}</div>`).join(''):'Sin incumplimientos heredados.';$('manualRejectList').innerHTML=manual.length?manual.map(x=>`<div class="manual-item"><button class="btn actions" onclick="removeManualReject(${x.id})">Quitar</button><b>${esc(x.detalle||'Detalle agregado')}</b>${x.motivacion?`<div>${esc(x.motivacion)}</div>`:''}${x.fundamento?`<div class="small">${esc(x.fundamento)}</div>`:''}</div>`).join(''):'Ninguno.';$('selectedDefs').innerHTML=e.defectIds.length?e.defectIds.map(code=>{let x=CATALOGO.find(v=>v.codigo===code);return `<div style="margin:4px 0"><b>✓ ${esc(code)}</b> — ${esc(x?.descripcion||'')}</div>`}).join(''):'Sin causales seleccionadas.';$('selectedCount').textContent=String(e.defectIds.length);$('selectedCount').className='right pill '+(e.defectIds.length?'red':'green')}
function saveQualification(){let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;e.calificacionEncargado=$('calificador').value.trim();e.fechaCalificacion=new Date().toISOString();let state=updateDecision(e);persist();renderAll();alert(state.decision==='PENDIENTE'?'Calificación guardada. El expediente continúa pendiente de completar la inspección.':`Calificación guardada: ${state.decision}.`)}
