function finalizeCase(){let e=expedientes.find(x=>x.id===currentClose);if(!e)return;let state=updateDecision(e);if(state.decision==='PENDIENTE'){alert('No se puede finalizar: falta completar la inspección y confirmar la comparación de anchos.');return}if(state.decision==='RECHAZADO'&&!state.reasons.length){alert('Un rechazo requiere motivos registrados.');return}saveReportFieldsSilent(e);if(!confirm(`Finalizar ${e.tramite} como ${state.decision}?`))return;e.dictamen=state.decision;e.finalizado=true;e.estado='FINALIZADO';e.fechaFin=new Date().toISOString().slice(0,10);persist();renderAll();loadClose(e.id)}
